                map.serialize_entry("type", "indexedAccess")?;
                map.serialize_entry("expression", expression)?;
            }
            OpaqueReason::UnsupportedExpression => map.serialize_entry("type", "unsupportedExpression")?,
        }
        map.end()
    }
}

